import { tracks, albums, artists, editorial, trackById, artUrl } from './data.js';
import { STORAGE_KEY, readState, moveItem, formatTime, escapeHtml as esc, searchTracks } from './core.js';

const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',library:'<path d="M4 4v16M9 4v16m5-16 6 16M4 8h5M4 16h5"/>',heart:'<path d="M20.5 4.9a5.5 5.5 0 0 0-7.8 0L12 5.6l-.7-.7a5.5 5.5 0 0 0-7.8 7.8L12 21l8.5-8.3a5.5 5.5 0 0 0 0-7.8Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',playlist:'<path d="M4 5h12M4 10h12M4 15h6M17 12v7a2 2 0 1 1-2-2h2m0-5 4-1v5"/>',play:'<path d="m9 5 11 7-11 7z"/>',pause:'<path d="M8 5h3v14H8zM15 5h3v14h-3z"/>',next:'<path d="m5 5 10 7-10 7zM19 5v14"/>',previous:'<path d="m19 5-10 7 10 7zM5 5v14"/>',shuffle:'<path d="M3 6h3c5 0 7 12 12 12h3m-4-4 4 4-4 4M3 18h3c2 0 3-2 4-4m4-4c1-2 2-4 4-4h3m-4-4 4 4-4 4"/>',repeat:'<path d="m17 2 4 4-4 4M3 11V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14-1v3a2 2 0 0 1-2 2H3"/>',repeatOne:'<path d="m17 2 4 4-4 4M3 11V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14-1v3a2 2 0 0 1-2 2H3m7-8 2-1v7"/>',queue:'<path d="M4 5h16M4 10h16M4 15h8M4 20h8m5-6 5 3-5 3z"/>',volume:'<path d="m3 9 5 0 5-4v14l-5-4H3zM17 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',mute:'<path d="m3 9 5 0 5-4v14l-5-4H3zm14 0 5 6m0-6-5 6"/>',expand:'<path d="M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6"/>',back:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m9 6 6 6-6 6"/>',bell:'<path d="M5 9a7 7 0 0 1 14 0v5l2 3H3l2-3zM9 21h6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',up:'<path d="m6 14 6-6 6 6"/>',down:'<path d="m6 10 6 6 6-6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',edit:'<path d="m15 4 5 5-11 11-6 1 1-6zM13 6l5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L20 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="17" cy="16" rx="3" ry="3"/>'};
const icon=(name,filled=false)=>`<svg viewBox="0 0 24 24" fill="${filled?'currentColor':'none'}" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.music}</svg>`;
const $=id=>document.getElementById(id);
let state=readState(localStorage), playing=false, homeFilter='All music', libraryFilter='All', searchFilter='All', searchQuery='', toastTimer, dragFrom=null;
let sessionOrder=[state.current,...state.queue], playHistory=[], routeStack=[];
const audio=$('audio'), modal=$('modal');
audio.volume=state.volume;
audio.src=`./assets/${state.current}.wav`;
const save=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast('Your browser could not save changes. They will last for this session.');}};
const route=()=>location.hash.slice(1)||'home';
const current=()=>trackById(state.current);
const queueOpen=()=>!$('queue-panel').hidden;
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function shuffleArray(list){return [...list].map(x=>({x,key:Math.random()})).sort((a,b)=>a.key-b.key).map(v=>v.x);}
function setRange(el,value){el.style.setProperty('--range-fill',`${value}%`);}
function cover(key,alt='',extra=''){return `<img src="${artUrl(key)}" alt="${esc(alt)}" ${extra}>`;}
function empty(title,description,action='search',button='Discover some music',symbol='music'){return `<div class="empty-state">${icon(symbol)}<h2>${esc(title)}</h2><p>${esc(description)}</p><a class="primary-button" href="#${action}" ${action==='search'?'data-action="reset-search"':''}>${esc(button)} ${icon('right')}</a></div>`;}
function button(action,name,label,extra=''){return `<button class="icon-button" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${extra}>${icon(name)}</button>`;}
function collection(type,id){if(type==='album')return albums.find(a=>a.id===id);if(type==='artist')return artists.find(a=>a.id===id);return [...editorial,...state.playlists].find(p=>p.id===id);}
function musicCard(item,type='album',tag=''){const isPlaying=playing&&item.trackIds?.includes(state.current);return `<article class="music-card ${isPlaying?'is-playing':''} ${type==='artist'?'artist-card':''}"><div class="cover-wrap"><a href="#${type}/${item.id}" aria-label="Open ${esc(item.title)}">${cover(item.art,item.title,'loading="lazy"')}</a>${tag?`<span class="card-tag">${esc(tag)}</span>`:''}<button class="card-play" data-action="play-collection" data-type="${type}" data-id="${item.id}" aria-label="Play ${esc(item.title)}">${icon('play',true)}</button></div><a href="#${type}/${item.id}"><h3>${esc(item.title)}</h3></a><p>${esc(item.artist||item.description||(type==='artist'?'Artist':`${item.trackIds.length} songs · By you`))}</p></article>`;}
function table(ids,{editable=false,playlistId='',limit=Infinity}={}){return `<div class="track-table ${editable?'editable-table':''}"><div class="table-header"><span>#</span><span>Title</span><span class="track-album">Album</span>${!editable?'<span class="track-genre">Genre</span>':''}<span></span><span style="text-align:right">${icon('clock')}</span>${editable?'<span></span>':''}</div>${ids.slice(0,limit).map((id,index)=>trackRow(id,index,editable,playlistId)).join('')}</div>`;}
function trackRow(id,index,editable=false,playlistId=''){const t=trackById(id);if(!t)return '';return `<div class="track-row ${state.current===id?'is-current':''}" data-track="${id}" ${editable?`draggable="true" data-index="${index}" data-playlist="${playlistId}"`:''}><button class="row-play track-number" data-action="play-track" data-id="${id}" aria-label="Play ${esc(t.title)}"><span class="number">${index+1}</span><span class="play-icon">${icon('play',true)}</span></button><div class="track-info"><a href="#album/${t.art}" aria-label="Open ${esc(t.album)}">${cover(t.art,'')}</a><div><button class="track-name" data-action="play-track" data-id="${id}">${esc(t.title)}</button><small><a href="#artist/${t.art}">${esc(t.artist)}</a></small></div></div><a class="track-album" href="#album/${t.art}">${esc(t.album)}</a>${!editable?`<span class="track-genre">${esc(t.genre)}</span>`:''}<button class="icon-button track-like ${state.liked.includes(id)?'saved':''}" data-action="like" data-id="${id}" aria-label="${state.liked.includes(id)?'Unsave':'Save'} ${esc(t.title)}" aria-pressed="${state.liked.includes(id)}">${icon('heart',state.liked.includes(id))}</button><div class="track-length"><span>${formatTime(t.duration)}</span>${!editable?button('track-menu','more',`Options for ${t.title}`,`data-id="${id}"`):''}</div>${editable?`<div class="reorder-controls">${button('move-track-up','up','Move track up',`data-playlist="${playlistId}" data-index="${index}" ${index===0?'disabled':''}`)}${button('move-track-down','down','Move track down',`data-playlist="${playlistId}" data-index="${index}"`)}${button('remove-track','close',`Remove ${t.title} from playlist`,`data-playlist="${playlistId}" data-index="${index}"`)}</div>`:''}</div>`;}
function navigation(){const active=route().split('/')[0];const links=[['home','home','Home'],['search','search','Search'],['library','library','Your library']];$('main-nav').innerHTML=links.map(([id,i,label])=>`<a class="nav-item ${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('');document.querySelector('.mobile-nav').innerHTML=links.map(([id,i,label])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('')+`<button data-action="queue" class="${queueOpen()?'active':''}">${icon('queue')}Queue</button>`;$('sidebar-playlists').innerHTML=state.playlists.map(p=>`<a class="playlist-link ${route()===`playlist/${p.id}`?'active':''}" href="#playlist/${p.id}">${icon('playlist')}<span>${esc(p.title)}</span></a>`).join('');$('liked-count').textContent=`${state.liked.length} songs · Just your favorites`;}
function home(){const affinity=a=>a.trackIds.reduce((sum,id)=>sum+(state.liked.includes(id)?2:0)+(state.recent.includes(id)?6/(state.recent.indexOf(id)+1):0),0)+state.liked.filter(id=>trackById(id)?.genre===a.genre).length*.3;const ranked=[...albums].sort((a,b)=>affinity(b)-affinity(a));const selected=homeFilter==='All music'?ranked:ranked.filter(a=>a.genre===homeFilter||a.trackIds.some(id=>trackById(id).mood===homeFilter));return `<div class="welcome"><div><div class="eyebrow">YOUR DAILY DOSE OF GOOD MUSIC</div><h1>Find your next favorite.</h1><p>A familiar feeling. A whole new discovery.</p></div><div class="date-note">${icon('sun')} A good day for good music</div></div><div class="filter-row">${['All music','Chill','Focus','Indie','Electronic','Jazz'].map(f=>`<button class="filter-chip ${homeFilter===f?'active':''}" data-action="home-filter" data-value="${f}" aria-pressed="${homeFilter===f}">${f}</button>`).join('')}</div><section class="hero" aria-label="Featured playlist"><img class="hero-art" src="./assets/hero.svg" alt="An amber sun over a surreal violet desert"><div class="hero-content"><div class="hero-label"><span></span>PRIZIFY SELECTS</div><h2>Lose yourself.<br>Find your sound.</h2><p>Let the day fade out. A handpicked soundtrack<br>for your golden-hour state of mind.</p><div class="hero-actions"><button class="primary-button" data-action="play-collection" data-type="playlist" data-id="golden-hour">${icon('play',true)} Play the feeling</button><a class="outline-button" href="#playlist/golden-hour">Explore playlist ${icon('right')}</a></div></div><span class="hero-caption">GOLDEN HOUR, ON REPEAT</span><span class="hero-counter" aria-hidden="true"><i></i><i></i><i></i></span></section><section class="music-section"><div class="section-heading"><div><h2>${homeFilter==='All music'?'Your next obsession':`${esc(homeFilter)} sounds, just for you`}</h2><p>${homeFilter==='All music'?'Inspired by your likes and recent listening.':'A change of pace for your day.'}</p></div><a href="#discover">View all ${icon('right')}</a></div><div class="card-grid">${selected.map(a=>musicCard(a)).join('')}</div></section><section class="music-section"><div class="section-heading"><div><h2>Made for your moment</h2><p>Whatever the mood, we have a mix.</p></div><a href="#mixes">Explore mixes ${icon('right')}</a></div><div class="moment-grid">${[editorial[1],editorial[2],editorial[3]].map(p=>`<article class="moment-card"><a href="#playlist/${p.id}" aria-label="Open ${esc(p.title)}">${cover(p.art,'','loading="lazy"')}</a><a href="#playlist/${p.id}"><small>${p.tag}</small><h3>${p.title}</h3><p>${p.description}</p></a>${button('play-collection','play',`Play ${p.title}`,`data-type="playlist" data-id="${p.id}"`)}</article>`).join('')}</div></section><section class="music-section"><div class="section-heading"><div><h2>Back in your rotation</h2><p>Some things just sound better the second time.</p></div><a href="#recent">View history ${icon('right')}</a></div>${state.recent.length?table(state.recent,{limit:4}):empty('Your listening story starts here','Play a song to find it in your recent history.')}</section>`;}
function searchPage(){return `<div class="search-page-heading"><div class="eyebrow">FOLLOW YOUR CURIOSITY</div><h1>A world of sound awaits.</h1><p>Find a song, an artist, or a whole new obsession.</p></div><label class="big-search">${icon('search')}<input id="page-search" type="search" placeholder="Songs, artists, albums, playlists…" value="${esc(searchQuery)}" aria-label="Search songs, artists, albums, and playlists" autocomplete="off"></label><div class="filter-row">${['All','Songs','Artists','Albums','Playlists'].map(f=>`<button class="filter-chip ${searchFilter===f?'active':''}" data-action="search-filter" data-value="${f}" aria-pressed="${searchFilter===f}">${f}</button>`).join('')}</div><div id="search-results">${searchResults()}</div>`;}
function searchResults(){if(!searchQuery.trim())return `<section class="search-section"><h2>Browse a little. Discover a lot.</h2><div class="browse-grid">${[['Electronic','midnight','For the night owls'],['Focus','soft','Room for a little clarity'],['Indie','coast','A different kind of feeling'],['Jazz','sunday','Nothing to rush for'],['Ambient','bloom','Let your mind wander'],['Chill','golden','Your everyday exhale']].map(([g,a,s])=>`<button class="genre-card" data-action="browse-genre" data-value="${g}"><h3>${g}</h3><span>${s}</span>${cover(a,'')}</button>`).join('')}</div><div class="search-section"><h2>Start somewhere good</h2><div class="card-grid">${editorial.slice(0,3).map(p=>musicCard(p,'playlist')).join('')}</div></div></section>`;const q=searchQuery.toLowerCase().trim(), foundTracks=searchTracks(q),foundAlbums=albums.filter(a=>`${a.title} ${a.artist} ${a.genre}`.toLowerCase().includes(q)),foundArtists=artists.filter(a=>`${a.title} ${a.genre}`.toLowerCase().includes(q)),foundPlaylists=[...editorial,...state.playlists].filter(p=>`${p.title} ${p.description||''} ${p.trackIds.map(id=>trackById(id)?.genre).join(' ')}`.toLowerCase().includes(q));let sections=[];if(['All','Songs'].includes(searchFilter)&&foundTracks.length)sections.push(`<section class="search-section"><h2>Songs</h2>${table(foundTracks.map(t=>t.id))}</section>`);if(['All','Artists'].includes(searchFilter)&&foundArtists.length)sections.push(`<section class="search-section"><h2>Artists</h2><div class="search-result-artists">${foundArtists.map(a=>`<a class="search-artist" href="#artist/${a.id}">${cover(a.art,'')}<div><strong>${esc(a.title)}</strong><small>Artist · ${a.genre}</small></div></a>`).join('')}</div></section>`);if(['All','Albums'].includes(searchFilter)&&foundAlbums.length)sections.push(`<section class="search-section"><h2>Albums</h2><div class="card-grid">${foundAlbums.map(a=>musicCard(a)).join('')}</div></section>`);if(['All','Playlists'].includes(searchFilter)&&foundPlaylists.length)sections.push(`<section class="search-section"><h2>Playlists</h2><div class="card-grid">${foundPlaylists.map(p=>musicCard(p,'playlist')).join('')}</div></section>`);return sections.length?`<p class="result-count">Discoveries for “${esc(searchQuery)}”</p>${sections.join('')}`:empty('No matches. Yet.','Try a different title, artist, genre, or mood. Your next favorite is out there.','search','Browse all music','search');}
function library(){let items=[];if(['All','Playlists'].includes(libraryFilter))items.push(...state.playlists.map(p=>musicCard(p,'playlist')));if(['All','Albums'].includes(libraryFilter))items.push(...albums.filter(a=>state.savedAlbums.includes(a.id)).map(a=>musicCard(a)));if(['All','Artists'].includes(libraryFilter))items.push(...artists.filter(a=>state.followedArtists.includes(a.id)).map(a=>musicCard(a,'artist')));return `<div class="page-title-row"><div><div class="eyebrow">A COLLECTION THAT SOUNDS LIKE YOU</div><h1>Your library</h1><p>The good stuff. All in one place.</p></div><button class="primary-button" data-action="create-playlist">${icon('plus')} Create playlist</button></div><div class="filter-row">${['All','Playlists','Songs','Albums','Artists'].map(f=>`<button class="filter-chip ${libraryFilter===f?'active':''}" data-action="library-filter" data-value="${f}" aria-pressed="${libraryFilter===f}">${f}</button>`).join('')}</div>${libraryFilter==='Songs'?(state.liked.length?table(state.liked):empty('Make room for your favorites','Tap the heart beside any track to save it here.')):`<div class="library-grid">${libraryFilter==='All'?`<article class="music-card"><div class="cover-wrap"><a class="library-liked-cover" href="#liked" aria-label="Open liked songs">${icon('heart',true)}</a></div><a href="#liked"><h3>Liked songs</h3></a><p>${state.liked.length} songs · Your favorites</p></article>`:''}${items.join('')}</div>${!items.length&&libraryFilter!=='All'?empty(`Your ${libraryFilter.toLowerCase()} belong here`,libraryFilter==='Playlists'?'Create a playlist and give your day its own soundtrack.':`Save your favorite ${libraryFilter.toLowerCase()} as you explore. They'll be waiting here.`):''}`}`;}
function detail(type,id){const liked=type==='liked';const item=liked?{title:'Liked songs',description:'Every little song you fell in love with.',art:'liked',trackIds:state.liked}:collection(type,id);if(!item)return empty('That collection wandered off','It may have been deleted. Find something new to listen to.','library','Back to your library');const own=state.playlists.some(p=>p.id===id),isArtist=type==='artist',ids=item.trackIds||[],saved=type==='album'?state.savedAlbums.includes(id):isArtist?state.followedArtists.includes(id):state.playlists.some(p=>p.originalId===id);return `<section class="detail-hero ${isArtist?'artist':''}"><div class="detail-art">${liked?`<div class="library-liked-cover">${icon('heart',true)}</div>`:cover(item.art,item.title)}</div><div><div class="detail-eyebrow">${liked?'YOUR FAVORITES':isArtist?'ARTIST':type==='album'?'ALBUM':own?'YOUR PLAYLIST':item.tag||'PRIZIFY PLAYLIST'}</div><h1>${esc(item.title)}</h1><p class="detail-description">${esc(item.description||(isArtist?`${item.genre} for wherever your day takes you.`:`An original ${item.genre.toLowerCase()} session by ${item.artist}.`))}</p><div class="detail-meta"><span class="brand-dot">p</span><strong>${own||liked?'You':item.artist||'Prizify'}</strong><span>·</span><span>${ids.length} songs</span><span>·</span><span>${formatTime(ids.reduce((sum,t)=>sum+(trackById(t)?.duration||0),0))}</span></div></div></section><div class="detail-toolbar"><button class="detail-play" data-action="play-detail" data-type="${type}" data-id="${id||''}" aria-label="Play ${esc(item.title)}" ${!ids.length?'disabled':''}>${icon('play',true)}</button>${button('shuffle','shuffle','Toggle shuffle',`aria-pressed="${state.shuffle}"`)}${!own&&!liked?`<button class="outline-button" data-action="save-collection" data-type="${type}" data-id="${id}">${icon(saved?'check':'plus')}${saved?(isArtist?'Following':'Saved'):(isArtist?'Follow':'Save '+(type==='album'?'album':'playlist'))}</button>`:''}<div class="toolbar-end">${own?`<button class="outline-button" data-action="rename-playlist" data-id="${id}">${icon('edit')} Rename</button>${button('delete-playlist','trash','Delete playlist',`data-id="${id}"`)}`:''}${button('queue','queue','Open queue')}</div></div><div class="app-notice">${icon('info')}<span>Original demo recordings. The artists and releases are fictional; every track here plays.</span><button data-action="about">About the music</button></div>${ids.length?table(ids,{editable:own,playlistId:id}):empty(own?'Every great playlist starts with one song.':'Your favorites are waiting to happen.',own?'Add a few tracks below and make this mix your own.':'Tap the heart on any song. We’ll keep it right here.')} ${own?addSuggestions(item):''}`;}
function addSuggestions(p){const available=tracks.filter(t=>!p.trackIds.includes(t.id));return `<section class="add-tracks"><div class="add-tracks-heading"><h2>${available.length?'Make it your kind of mix':'You have the whole collection'}</h2><a class="text-button" href="#search">Search music ${icon('right')}</a></div><p>${available.length?'A few tracks that would feel right at home.':'Every demo song is in this playlist. Drag tracks or use the arrows to arrange your mix.'}</p>${available.slice(0,5).map(t=>`<div class="add-track-row">${cover(t.art,'')}<div><strong>${esc(t.title)}</strong><small>${esc(t.artist)}</small></div><button class="outline-button" data-action="add-to-playlist" data-playlist="${p.id}" data-id="${t.id}">${icon('plus')} Add</button></div>`).join('')}</section>`;}
function collectionPage(kind){const recent=kind==='recent',all=kind==='discover',items=all?albums:editorial;return `<div class="page-title-row"><div><div class="eyebrow">${recent?'PLAY IT AGAIN':all?'A LITTLE OUTSIDE YOUR USUAL':'EVERY MOOD HAS ITS MUSIC'}</div><h1>${recent?'Your recent rotation':all?'Find a new obsession':'A mix for every moment'}</h1><p>${recent?'The soundtrack to your lately.':all?'Independent sounds. Something that stays with you.':'Curated with care. Ready when you are.'}</p></div></div>${recent?(state.recent.length?table(state.recent):empty('A fresh start','Play a song and your recent listening will appear here.')):`<div class="library-grid">${items.map(p=>musicCard(p,all?'album':'playlist')).join('')}</div>`}`;}
function render(){const r=route(),[page,id]=r.split('/');let html;if(page==='home')html=home();else if(page==='search')html=searchPage();else if(page==='library')html=library();else if(['playlist','album','artist','liked'].includes(page))html=detail(page,id);else if(['discover','mixes','recent'].includes(page))html=collectionPage(page);else html=empty('A little off track','Let’s get you back to the music.','home','Go home');$('content').innerHTML=html;const crumb=page==='home'?'Home':page==='search'?'Search':page==='library'?'Your library':page==='liked'?'Liked songs':collection(page,id)?.title||({recent:'Recently played',discover:'Discover albums',mixes:'Mixes'}[page]||'Explore');$('breadcrumb').innerHTML=`${['playlist','album','artist','liked','library'].includes(page)?'Your music':'Discover'} <span>/</span> ${esc(crumb)}`;document.title=`${crumb} — Prizify`;navigation();syncRows();}

function syncRows(){document.querySelectorAll('[data-action="move-track-down"]').forEach(el=>{const p=state.playlists.find(p=>p.id===el.dataset.playlist);el.disabled=Number(el.dataset.index)>=(p?.trackIds.length||0)-1;});document.querySelectorAll('[data-action="shuffle"]').forEach(el=>{el.classList.toggle('is-active',state.shuffle);el.setAttribute('aria-pressed',state.shuffle);});document.querySelectorAll('.track-row').forEach(row=>row.classList.toggle('is-current',row.dataset.track===state.current));document.body.classList.toggle('paused',!playing);}
function syncPlayer(){const t=current();$('player-art').innerHTML=cover(t.art,t.album);$('player-title').textContent=t.title;$('player-artist').textContent=t.artist;$('duration').textContent=formatTime(t.duration);$('play-pause').innerHTML=icon(playing?'pause':'play',true);$('play-pause').setAttribute('aria-label',playing?'Pause':'Play');const liked=state.liked.includes(t.id);$('player-like').innerHTML=icon('heart',liked);$('player-like').classList.toggle('is-active',liked);$('player-like').setAttribute('aria-label',liked?'Unsave current track':'Save current track');$('player-like').setAttribute('aria-pressed',liked);$('shuffle').classList.toggle('is-active',state.shuffle);$('shuffle').setAttribute('aria-pressed',state.shuffle);$('repeat').innerHTML=icon(state.repeat==='one'?'repeatOne':'repeat');$('repeat').classList.toggle('is-active',state.repeat!=='off');$('repeat').setAttribute('aria-label',`Repeat ${state.repeat}`);$('repeat').setAttribute('aria-pressed',state.repeat!=='off');$('mute').innerHTML=icon(audio.muted||state.volume===0?'mute':'volume');$('mute').setAttribute('aria-label',audio.muted?'Unmute':'Mute');$('volume').value=state.volume;setRange($('volume'),state.volume*100);syncRows();updateExpanded();if(queueOpen())renderQueue();}
async function resume(){try{await audio.play();}catch(e){playing=false;syncPlayer();toast('Playback could not start. Tap play to try again.');}}
function recordRecent(id){state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,12);}
function loadTrack(id,{autoplay=true,history=true}={}){if(!trackById(id))return;if(history&&id!==state.current)playHistory.push(state.current);state.current=id;audio.src=`./assets/${id}.wav`;audio.currentTime=0;playing=false;recordRecent(id);save();$('elapsed').textContent='0:00';$('seek').value=0;setRange($('seek'),0);syncPlayer();if(autoplay)resume();}
function startList(ids,index=0){if(!ids.length){toast('Add a song to start listening.');return;}sessionOrder=[...ids];let following=ids.slice(index+1);if(state.shuffle)following=shuffleArray(ids.filter((_,i)=>i!==index));state.queue=following;loadTrack(ids[index]);}
function togglePlay(){if(playing)audio.pause();else resume();}
function next(ended=false){if(ended&&state.repeat==='one'){audio.currentTime=0;resume();return;}if(state.queue.length){const at=state.shuffle?Math.floor(Math.random()*state.queue.length):0;const id=state.queue.splice(at,1)[0];loadTrack(id);return;}if(state.repeat==='all'&&sessionOrder.length){state.queue=state.shuffle?shuffleArray(sessionOrder):[...sessionOrder];const id=state.queue.shift();loadTrack(id);return;}audio.pause();if(!ended)toast('You’re all caught up. Add something to the queue.');syncPlayer();}
function previous(){if(audio.currentTime>3){audio.currentTime=0;return;}const id=playHistory.pop();if(id){state.queue.unshift(state.current);loadTrack(id,{history:false});}else audio.currentTime=0;}
function toggleLike(id){const was=state.liked.includes(id);state.liked=was?state.liked.filter(x=>x!==id):[...state.liked,id];save();navigation();syncPlayer();document.querySelectorAll(`.track-row[data-track="${id}"] .track-like`).forEach(el=>{el.classList.toggle('saved',!was);el.setAttribute('aria-pressed',String(!was));el.setAttribute('aria-label',`${was?'Save':'Unsave'} ${trackById(id).title}`);el.innerHTML=icon('heart',!was);});if(route()==='liked'||route()==='library'&&libraryFilter==='Songs')render();toast(was?'Removed from liked songs':'Saved to your liked songs');}
function renderQueue(){const panel=$('queue-panel');panel.innerHTML=`<div class="queue-header"><h2>Your queue</h2>${button('queue','close','Close queue')}</div><div class="queue-subtitle">Now playing</div><div class="queue-track current">${cover(current().art,'')}<div><strong>${esc(current().title)}</strong><small>${esc(current().artist)}</small></div><button class="icon-button" data-action="toggle-play" aria-label="${playing?'Pause':'Play'}">${icon(playing?'pause':'play',true)}</button></div><div class="queue-subtitle">Up next · ${state.queue.length} ${state.queue.length?'<button class="queue-clear" data-action="clear-queue">Clear queue</button>':''}</div>${state.queue.length?state.queue.map((id,i)=>{const t=trackById(id);return `<div class="queue-track" draggable="true" data-queue-index="${i}">${cover(t.art,'')}<div><button class="track-name" data-action="play-queue" data-index="${i}">${esc(t.title)}</button><small>${esc(t.artist)}</small></div><div class="queue-controls">${button('queue-up','up','Move queued song up',`data-index="${i}" ${i===0?'disabled':''}`)}${button('queue-down','down','Move queued song down',`data-index="${i}" ${i===state.queue.length-1?'disabled':''}`)}${button('queue-remove','close',`Remove ${t.title} from queue`,`data-index="${i}"`)}</div></div>`;}).join(''):`<div class="queue-empty">A little breathing room.<br>Use the ··· beside any song to add it here.<br><br><a class="primary-button" href="#search" data-action="close-queue">Find your next song ${icon('right')}</a></div>`}`;}
function toggleQueue(force){const open=typeof force==='boolean'?force:!queueOpen();$('queue-panel').hidden=!open;$('queue-button').setAttribute('aria-expanded',open);$('queue-button').classList.toggle('is-active',open);if(open){renderQueue();$('queue-panel').querySelector('button')?.focus();}navigation();}
function showModal(title,body){$('modal-content').innerHTML=`<div class="modal-heading"><h2>${esc(title)}</h2>${button('close-modal','close','Close dialog')}</div>${body}`;if(!modal.open)modal.showModal();}
function playlistForm(id=null,addId=null){const p=state.playlists.find(p=>p.id===id);showModal(p?'Give it a new name':'Make it your own',`<form id="playlist-form" data-id="${p?.id||''}" data-add="${addId||''}"><p style="font-size:12px;color:#a2a2ae;line-height:1.8">${p?'A new name, the same good music.':'For a feeling, a person, or a perfectly ordinary Tuesday.'}</p><label class="field-label" for="playlist-name">Playlist name</label><input class="text-field" id="playlist-name" name="title" required maxlength="60" placeholder="My new favorite mix" value="${esc(p?.title||'')}" autocomplete="off"><label class="field-label" for="playlist-description">A little description <small>(optional)</small></label><input class="text-field" id="playlist-description" name="description" maxlength="160" placeholder="What’s the mood?" value="${esc(p?.description||'')}"><div class="modal-actions"><button class="outline-button" type="button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit">${p?'Save changes':'Create playlist'}</button></div></form>`);setTimeout(()=>$('playlist-name')?.focus(),0);}
function addSongDialog(id){const t=trackById(id);showModal('A home for this song',`<p style="font-size:12px;color:#aaaab4;margin-bottom:15px">Add “${esc(t.title)}” to a playlist.</p>${state.playlists.map(p=>`<button class="pick-playlist" data-action="add-to-playlist" data-playlist="${p.id}" data-id="${id}" ${p.trackIds.includes(id)?'disabled':''}>${cover(p.art,'')}<span>${esc(p.title)}<small>${p.trackIds.includes(id)?'Already in this playlist':`${p.trackIds.length} songs`}</small></span></button>`).join('')}<button class="pick-playlist" data-action="create-with-song" data-id="${id}">${icon('plus')} Create a new playlist</button>`);}
function trackMenu(id){const t=trackById(id);showModal(t.title,`<div class="modal-body"><p>${esc(t.artist)} · ${esc(t.album)}</p><button class="pick-playlist" data-action="play-next" data-id="${id}">${icon('next')} Play next</button><button class="pick-playlist" data-action="add-queue" data-id="${id}">${icon('queue')} Add to queue</button><button class="pick-playlist" data-action="song-playlists" data-id="${id}">${icon('playlist')} Add to playlist</button><button class="pick-playlist" data-action="like-menu" data-id="${id}">${icon('heart',state.liked.includes(id))}${state.liked.includes(id)?'Remove from':'Save to'} liked songs</button><a class="pick-playlist" href="#album/${t.art}" data-action="close-modal">${icon('music')} Go to album</a></div>`);}
function saveCollection(type,id){const item=collection(type,id);if(!item)return;if(type==='album'||type==='artist'){const key=type==='album'?'savedAlbums':'followedArtists';const had=state[key].includes(id);state[key]=had?state[key].filter(x=>x!==id):[...state[key],id];toast(had?'Removed from your library':type==='artist'?`You’re now following ${item.title}`:'Album saved to your library');}else{const existing=state.playlists.find(p=>p.originalId===id);if(existing){toast('This mix is in your library. You can edit it there.');location.hash=`playlist/${existing.id}`;return;}state.playlists.push({...item,id:'p-'+crypto.randomUUID(),originalId:id,trackIds:[...item.trackIds]});toast('Playlist saved. Make this mix your own in your library.');}save();render();}
function showNowPlaying(){showModal('In your headphones',`<div class="now-playing-modal"><img id="expanded-art" src="${artUrl(current().art)}" alt="${esc(current().album)}"><h2 id="expanded-title">${esc(current().title)}</h2><p id="expanded-artist">${esc(current().artist)} · ${esc(current().album)}</p><div class="expanded-seek"><time id="modal-elapsed">${formatTime(audio.currentTime)}</time><input id="modal-seek" type="range" min="0" max="100" step=".1" value="${audio.duration?audio.currentTime/audio.duration*100:0}" aria-label="Seek in expanded player"><time id="modal-duration">${formatTime(current().duration)}</time></div><div class="expanded-controls">${button('shuffle','shuffle','Shuffle in expanded player','id="expanded-shuffle"')}${button('previous','previous','Previous track in expanded player')}<button id="expanded-play" class="main-play" data-action="toggle-play" aria-label="Play in expanded player"></button>${button('next','next','Next track in expanded player')}${button('repeat','repeat','Repeat in expanded player','id="expanded-repeat"')}</div><div class="expanded-volume">${button('mute','volume','Mute in expanded player','id="expanded-mute"')}<input id="modal-volume" type="range" min="0" max="1" step=".01" value="${state.volume}" aria-label="Volume in expanded player"></div><p style="font-size:10px;margin-top:17px">Original Prizify demo recording · Tap outside to return</p></div>`);updateExpanded();}
function updateExpanded(){if(!$('expanded-play'))return;$('expanded-art').src=artUrl(current().art);$('expanded-art').alt=current().album;$('expanded-title').textContent=current().title;$('expanded-artist').textContent=`${current().artist} · ${current().album}`;$('expanded-play').innerHTML=icon(playing?'pause':'play',true);$('expanded-play').setAttribute('aria-label',`${playing?'Pause':'Play'} in expanded player`);$('expanded-shuffle').classList.toggle('is-active',state.shuffle);$('expanded-shuffle').setAttribute('aria-pressed',state.shuffle);$('expanded-repeat').classList.toggle('is-active',state.repeat!=='off');$('expanded-repeat').setAttribute('aria-label',`Repeat ${state.repeat} in expanded player`);$('expanded-repeat').innerHTML=icon(state.repeat==='one'?'repeatOne':'repeat');$('expanded-mute').innerHTML=icon(audio.muted?'mute':'volume');$('modal-volume').value=state.volume;setRange($('modal-volume'),state.volume*100);const percent=audio.duration?audio.currentTime/audio.duration*100:0;$('modal-seek').value=percent;setRange($('modal-seek'),percent);$('modal-elapsed').textContent=formatTime(audio.currentTime);$('modal-duration').textContent=formatTime(current().duration);}
function about(){showModal('Independent by design.',`<div class="modal-body"><p>Welcome to <strong>Prizify</strong> — a little less noise, a little more music.</p><p>This is a fully interactive demo. All 12 instrumental recordings and the cover illustrations were created for this project. The artists, albums, and song titles are fictional; there are no commercial recordings or third-party music APIs.</p><p>Listen, build a playlist, and make yourself at home. Your library, queue, and preferences stay in this browser. This demo has no account system or cross-device sync.</p><p>Keyboard shortcuts: <strong>Space</strong> play/pause · <strong>← / →</strong> seek 5 seconds · <strong>M</strong> mute · <strong>/</strong> search · <strong>Esc</strong> close.</p><div class="modal-actions"><button class="primary-button" data-action="close-modal">Find my frequency ${icon('right')}</button></div></div>`);}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id,type,value,playlist,index}=el.dataset;const i=Number(index);switch(action){
  case 'toggle-play':togglePlay();break;
  case 'play-track':{const visible=[...document.querySelectorAll('.track-row')].map(row=>row.dataset.track);startList(visible.length?visible:tracks.map(t=>t.id),Math.max(0,visible.indexOf(id)));break;}
  case 'play-collection':{const p=collection(type,id);if(p)startList(p.trackIds);break;}
  case 'play-detail':startList(type==='liked'?state.liked:collection(type,id)?.trackIds||[]);break;
  case 'previous':previous();break;
  case 'next':next();break;
  case 'shuffle':state.shuffle=!state.shuffle;save();syncPlayer();toast(`Shuffle ${state.shuffle?'on':'off'}`);break;
  case 'repeat':state.repeat=({off:'all',all:'one',one:'off'})[state.repeat];save();syncPlayer();toast(`Repeat ${state.repeat==='off'?'off':state.repeat==='all'?'queue':'one song'}`);break;
  case 'mute':audio.muted=!audio.muted;syncPlayer();break;
  case 'like':toggleLike(id);break;
  case 'like-current':toggleLike(state.current);break;
  case 'like-menu':toggleLike(id);modal.close();break;
  case 'queue':toggleQueue();break;
  case 'close-queue':toggleQueue(false);break;
  case 'clear-queue':state.queue=[];save();renderQueue();toast('Queue cleared. A fresh start.');break;
  case 'queue-remove':state.queue.splice(i,1);save();renderQueue();break;
  case 'queue-up':case 'queue-down':state.queue=moveItem(state.queue,i,i+(action==='queue-up'?-1:1));save();renderQueue();break;
  case 'play-queue':{const nextId=state.queue.splice(i,1)[0];loadTrack(nextId);break;}
  case 'play-next':state.queue.unshift(id);save();modal.close();if(queueOpen())renderQueue();toast('Playing next. Good choice.');break;
  case 'add-queue':state.queue.push(id);save();modal.close();if(queueOpen())renderQueue();toast('Added to your queue');break;
  case 'track-menu':trackMenu(id);break;
  case 'song-playlists':addSongDialog(id);break;
  case 'create-playlist':playlistForm();break;
  case 'create-with-song':playlistForm(null,id);break;
  case 'rename-playlist':playlistForm(id);break;
  case 'delete-playlist':{const p=state.playlists.find(p=>p.id===id);showModal('Let this playlist go?',`<div class="modal-body"><p>“${esc(p.title)}” will be removed from your library. Your liked songs will stay with you.</p><div class="modal-actions"><button class="outline-button" data-action="close-modal">Keep playlist</button><button class="danger-button" data-action="confirm-delete" data-id="${id}">Delete playlist</button></div></div>`);break;}
  case 'confirm-delete':state.playlists=state.playlists.filter(p=>p.id!==id);save();modal.close();location.hash='library';toast('Playlist deleted');break;
  case 'add-to-playlist':{const p=state.playlists.find(p=>p.id===playlist);if(p&&!p.trackIds.includes(id)){p.trackIds.push(id);save();toast(`Added to ${p.title}`);if(modal.open)modal.close();render();}else toast('That song is already in this playlist.');break;}
  case 'remove-track':{const p=state.playlists.find(p=>p.id===playlist);p.trackIds.splice(i,1);save();render();toast('Song removed from this playlist');break;}
  case 'move-track-up':case 'move-track-down':{const p=state.playlists.find(p=>p.id===playlist);p.trackIds=moveItem(p.trackIds,i,i+(action==='move-track-up'?-1:1));save();render();break;}
  case 'save-collection':saveCollection(type,id);break;
  case 'home-filter':homeFilter=value;render();break;
  case 'library-filter':libraryFilter=value;render();break;
  case 'reset-search':searchQuery='';searchFilter='All';$('global-search').value='';if(route()==='search')render();break;
  case 'search-filter':searchFilter=value;render();break;
  case 'browse-genre':searchQuery=value;searchFilter='All';$('global-search').value=value;render();break;
  case 'close-modal':modal.close();break;
  case 'open-current':location.hash=`album/${current().art}`;break;
  case 'now-playing':showNowPlaying();break;
  case 'back':if(routeStack.length>1){routeStack.pop();const last=routeStack.pop();location.hash=last||'home';}else location.hash='home';break;
  case 'about':about();break;
  case 'profile':showModal('Your own corner of sound.',`<div class="modal-body"><p>You’re listening as a guest. No sign-up, no interruptions — just good music.</p><p><strong>${state.liked.length}</strong> liked songs · <strong>${state.playlists.length}</strong> playlists · <strong>${state.savedAlbums.length}</strong> saved albums</p><p>Your collection is saved on this device. To take it with you, export a copy and import it in another Prizify browser.</p><button class="pick-playlist" data-action="export-library">${icon('library')} Export your library</button><label class="pick-playlist" style="cursor:pointer">${icon('plus')} Import a library<input type="file" id="import-library" accept=".json,application/json" class="sr-only"></label></div>`);break;
  case 'export-library':{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='prizify-library.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your library, ready to travel');break;}
  case 'activity':showModal('A fresh frequency.',`<div class="modal-body"><p><strong>Welcome to Prizify, Volume 01.</strong></p><p>Six independent releases. Twelve original recordings. A world of moods to make your own.</p><p>Start with <em>Golden Hour</em> for warm electronic textures, <em>Soft Focus</em> for a quiet afternoon, or <em>Midnight Motion</em> for the long way home.</p><div class="modal-actions"><a class="primary-button" href="#discover" data-action="close-modal">Explore the releases ${icon('right')}</a></div></div>`);break;
}});
document.addEventListener('submit',e=>{if(e.target.id!=='playlist-form')return;e.preventDefault();const form=e.target,values=new FormData(form),title=String(values.get('title')).trim(),description=String(values.get('description')).trim();if(!title){$('playlist-name').setCustomValidity('Give your playlist a name.');$('playlist-name').reportValidity();return;}let p=state.playlists.find(p=>p.id===form.dataset.id);if(p){p.title=title;p.description=description;toast('A fresh name for a good mix');}else{p={id:'p-'+crypto.randomUUID(),title,description,art:['first','move','mix','focus'][state.playlists.length%4],trackIds:form.dataset.add?[form.dataset.add]:[]};state.playlists.push(p);toast('Your new playlist is ready');}save();modal.close();if(route()===`playlist/${p.id}`)render();else location.hash=`playlist/${p.id}`;});
document.addEventListener('input',e=>{if(e.target.id==='playlist-name')e.target.setCustomValidity('');if(e.target.id==='global-search'||e.target.id==='page-search'){searchQuery=e.target.value;if(e.target.id==='global-search'){if(route()!=='search')location.hash='search';else{const p=$('page-search');if(p)p.value=searchQuery;$('search-results').innerHTML=searchResults();}}else{$('global-search').value=searchQuery;$('search-results').innerHTML=searchResults();}}if(e.target.id==='seek'&&Number.isFinite(audio.duration)){audio.currentTime=Number(e.target.value)/100*audio.duration;setRange(e.target,e.target.value);}if(e.target.id==='modal-seek'&&Number.isFinite(audio.duration)){audio.currentTime=Number(e.target.value)/100*audio.duration;setRange(e.target,e.target.value);}if(e.target.id==='modal-volume'){state.volume=Number(e.target.value);audio.volume=state.volume;audio.muted=false;save();syncPlayer();}if(e.target.id==='volume'){state.volume=Number(e.target.value);audio.volume=state.volume;audio.muted=false;save();syncPlayer();}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-library')return;const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error();const raw=JSON.parse(await file.text());if(!Array.isArray(raw.playlists)||!Array.isArray(raw.liked))throw Error();state=readState({getItem:()=>JSON.stringify(raw)});save();audio.volume=state.volume;loadTrack(state.current,{autoplay:false});modal.close();render();toast('Welcome back. Your library is here.');}catch{toast('That file is not a valid Prizify library.');}});
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-playlist][data-index], [data-queue-index]');if(!row)return;dragFrom={playlist:row.dataset.playlist,index:Number(row.dataset.index??row.dataset.queueIndex),queue:row.dataset.queueIndex!==undefined};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragFrom.index));});
document.addEventListener('dragover',e=>{if(!dragFrom)return;const row=e.target.closest('.track-row,.queue-track');if(row){e.preventDefault();row.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>{e.target.closest('.track-row,.queue-track')?.classList.remove('drag-over');});
document.addEventListener('drop',e=>{if(!dragFrom)return;const row=e.target.closest('.track-row,.queue-track');if(!row)return;e.preventDefault();if(dragFrom.queue&&row.dataset.queueIndex!==undefined){state.queue=moveItem(state.queue,dragFrom.index,Number(row.dataset.queueIndex));save();renderQueue();}else if(!dragFrom.queue&&row.dataset.playlist===dragFrom.playlist){const p=state.playlists.find(p=>p.id===dragFrom.playlist);p.trackIds=moveItem(p.trackIds,dragFrom.index,Number(row.dataset.index));save();render();}dragFrom=null;});
document.addEventListener('dragend',()=>{dragFrom=null;document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));});
document.addEventListener('keydown',e=>{const input=e.target.closest('input,textarea,select,button,a,[contenteditable]');if(e.key==='Escape'){if(queueOpen())toggleQueue(false);return;}if(e.key==='/'&&!input&&!modal.open){e.preventDefault();$('global-search').focus();return;}if(input||modal.open)return;if(e.code==='Space'){e.preventDefault();togglePlay();}if(e.key==='ArrowRight'){e.preventDefault();audio.currentTime=Math.min(audio.duration||0,audio.currentTime+5);}if(e.key==='ArrowLeft'){e.preventDefault();audio.currentTime=Math.max(0,audio.currentTime-5);}if(e.key.toLowerCase()==='m'){audio.muted=!audio.muted;syncPlayer();}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
audio.addEventListener('play',()=>{playing=true;syncPlayer();});audio.addEventListener('pause',()=>{playing=false;syncPlayer();});audio.addEventListener('timeupdate',()=>{const percent=audio.duration?audio.currentTime/audio.duration*100:0;$('seek').value=percent;setRange($('seek'),percent);$('elapsed').textContent=formatTime(audio.currentTime);if($('modal-seek')){$('modal-seek').value=percent;setRange($('modal-seek'),percent);$('modal-elapsed').textContent=formatTime(audio.currentTime);}});audio.addEventListener('loadedmetadata',()=>{$('duration').textContent=formatTime(audio.duration);});audio.addEventListener('ended',()=>next(true));audio.addEventListener('error',()=>{if(audio.error){playing=false;syncPlayer();toast('This demo track could not load. Try another song.');}});
window.addEventListener('hashchange',()=>{routeStack.push(route());render();window.scrollTo({top:0,behavior:'instant'});if(queueOpen())toggleQueue(false);});
for(const [id,name] of [['sidebar-create','plus'],['liked-icon','heart'],['back-button','back'],['search-icon','search'],['notification-icon','bell'],['shuffle','shuffle'],['previous','previous'],['next','next'],['queue-button','queue'],['expand','expand']])$(id).innerHTML=icon(name,id==='liked-icon');
routeStack.push(route());render();syncPlayer();
